typedef float rational_t;
typedef float time_value_t;
typedef float vm_num_t;

template<class T>
inline const T& min(const T& a, const T& b) { return b < a ? b : a; }

class vm_stack {
public:
  int salloc;
  char* buffer;
  char* SP;
  void* my_thread;
  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

class script_manager {
  char pad[296];
  time_value_t time_inc;
public:
  time_value_t get_time_inc() const { return time_inc; }
};

class world_dynamics_system {
public:
  script_manager* get_script_manager() {
    return reinterpret_cast<script_manager*>(this);
  }
};
extern world_dynamics_system* g_world_ptr __asm__("g_world_ptr");

class fog_manager;
extern fog_manager* fog_manager_instance __asm__("_11fog_manager$instance");
class fog_manager {
  void* vtable;
  char fog_color[16];
  rational_t specified_fog_start_distance;
  rational_t specified_fog_end_distance;
public:
  static fog_manager* inst() { return fog_manager_instance; }
  rational_t get_fog_end_distance() const { return specified_fog_end_distance; }
  void set_fog_distance(rational_t, rational_t)
    __asm__("set_fog_distance__11fog_managerff");
};

class slf_wait_animate_fog_distance_t : public script_library_class::function
{
  public:
    struct sdata_t
    {
      time_value_t clock;
      vm_num_t     start_distance;
    };
    struct parms_t
    {
      vm_num_t dest_distance;
      vm_num_t duration;
    };
    virtual bool operator()(vm_stack& stack,entry_t entry)
    {
      sdata_t* sdata = (sdata_t*)stack.get_SP();
      stack.pop(sizeof(parms_t));
      parms_t* parms = (parms_t*)stack.get_SP();
      if (entry == FIRST_ENTRY)
      {
        if(parms->duration==0)
        {
          fog_manager::inst()->set_fog_distance( 0, parms->dest_distance );
          return true;
        }
        else
        {
          sdata->clock = 0.0f;
          sdata->start_distance = fog_manager::inst()->get_fog_end_distance();
          return false;
        }
      }
      else
      {
        sdata->clock += (g_world_ptr->get_script_manager()->get_time_inc());
        float percentage_elapsed = sdata->clock / parms->duration;
        percentage_elapsed = min( percentage_elapsed, 1.0f );
        rational_t distance = (parms->dest_distance - sdata->start_distance) * percentage_elapsed
                            + sdata->start_distance;
        fog_manager::inst()->set_fog_distance( 0, distance );
        if( sdata->clock >= parms->duration )
        {
          return true;
        }
        else
        {
          return false;
        }
      }
    }
};
